// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: amount sent and initial previous balance (we will simulate previous balance by first calling Put)
    function testFuzz_property(uint256 sendAmount, uint256 secondAmount) public {
        // keep amounts in reasonable gas/ether bounds but wide
        sendAmount = bound(sendAmount, 1 wei, 10 ether);
        secondAmount = bound(secondAmount, 1 wei, 10 ether);

        // deploy an attacker that will reenter Put during the external call path
        Attacker attacker = new Attacker(address(c));

        // fund attacker and a normal user
        vm.deal(address(attacker), sendAmount + secondAmount + 1 ether);

        // 1) Make attacker deposit an initial amount so Acc[attacker].balance > 0
        vm.prank(address(attacker));
        c.Put{value: sendAmount}(block.timestamp + 1);

        // read previous balance via public getter Acc(address).balance: Acc is public mapping, returns Holder, but solidity auto getter returns (unlockTime, balance)
        (uint prevUnlock, uint prevBal) = c.Acc(address(attacker));

        // Now we want to trigger a Put that will cause a reentrant call during the low-level external send inside Collect in reference vs mutant.
        // The Attacker is written so its fallback will reenter c.Put when it receives Ether. We now call c.Collect via a normal call that will send Ether back to attacker
        // First ensure attacker has enough recorded balance to Collect secondAmount
        // Increase recorded balance by calling Put again (this Put may be re-entered later when Collect triggers attacker fallback)
        vm.prank(address(attacker));
        c.Put{value: secondAmount}(block.timestamp + 1);

        // Now attacker will call Collect which will in turn call back to attacker when transferring funds; attacker.fallback will reenter Put
        // Give attacker enough chain balance to cover any outgoing sends if needed (already funded)
        vm.prank(address(attacker));
        // Wrap in try/catch because behavior might differ across reference and mutant
        bool ok;
        try c.Collect{value: 0}(secondAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the sequence, the invariant for the correct contract: the recorded balance for attacker equals prevBal + sendAmount + secondAmount - (ok ? secondAmount : 0)
        // But to make a single general property that the reference always satisfies: after a Put by an EOA sending value, that EOA's Acc.balance increases by exactly that value (atomic for each Put call).
        // We can check that the last Put (the second Put) increased the recorded balance by exactly secondAmount relative to the balance just before that Put.
        // We captured prevBal before the second Put (it was prevBal after first Put). After second Put, the recorded balance should be prevBal + secondAmount (regardless of later reentrancy during Collect).

        (uint unlockAfter, uint balAfter) = c.Acc(address(attacker));

        // single assert: the reference contract guarantees that immediately after a Put call completes, the caller's Acc.balance == previous_balance + msg.value
        // We assert that balAfter >= prevBal and that the increment equals sendAmount + secondAmount minus any collected amount. However to keep a single universal property that the correct contract satisfies for all inputs and mutant breaks for some,
        // we assert that the immediate effect of the second Put produced an increase of exactly secondAmount from prevBal.

        // compute observed increment
        // Note: some Collect may have reduced balance after Put if reentrancy allowed withdrawal during Put; the buggy mutant can cause that, violating this assertion for some inputs.
        assertTrue(balAfter == prevBal + secondAmount);
    }
}

// Attacker that re-enters Put in its fallback when receiving Ether
contract Attacker {
    C public target;
    bool public reentered;
    constructor(address _t) {
        target = C(_t);
        reentered = false;
    }
    fallback() external payable {
        // reenter only once to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // perform a reentrant Put call sending a tiny amount (must have balance)
            // call with 0 value to reenter logic path; Put requires payable, but passing 0 is allowed
            target.Put{value: 0}(block.timestamp + 1);
        }
    }
}

