pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: amount to send and a boolean toggling whether the caller is the attacker helper.
    function testFuzz_property(uint256 amount, bool useAttacker) public {
        // keep amount in a reasonable range and non-zero to matter relative to MinSum (1 ether)
        amount = bound(amount, 1 wei, 5 ether);

        // deploy attacker helper that will re-enter during Put when desired
        Attacker attacker = new Attacker(address(c));

        address caller = useAttacker ? address(attacker) : address(this);

        // fund the caller
        vm.deal(caller, amount + 1 ether);

        // read previous balance recorded in c for the caller
        uint256 prev = c.Acc(caller).balance;

        bool ok;
        if (useAttacker) {
            // attacker will attempt reentrancy in its fallback while receiving Put's internal operations
            // make attacker prepared to reenter with the same amount
            attacker.setReenterAmounts(amount);

            // perform the call from attacker
            vm.prank(caller);
            try c.Put{value: amount}(block.timestamp + 1) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // normal EOA call
            vm.prank(caller);
            try c.Put{value: amount}(block.timestamp + 1) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // After the call completes, the invariant for the correct contract: recorded balance == prev + amount
        // This is a single assertion reading c's public getter Acc
        uint256 finalBal = c.Acc(caller).balance;
        assertTrue(finalBal == prev + (ok ? amount : 0));
    }
}

// Attacker helper: when funded and used as caller, its fallback will re-enter C.Put to try to exploit missing lock.
contract Attacker {
    C public target;
    uint256 public reenterAmount;

    constructor(address _t) {
        target = C(_t);
    }

    function setReenterAmounts(uint256 amt) public {
        reenterAmount = amt;
    }

    fallback() external payable {
        // Attempt a reentrant Put call only if we have positive reenterAmount and some gas
        if (reenterAmount > 0) {
            // try to re-enter; ignore revert
            try target.Put{value: reenterAmount}(block.timestamp + 1) {
                // do nothing
            } catch {
                // ignore
            }
        }
    }
}

