pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: amount to send and a flag to choose whether the caller is the attacker
    function testFuzz_property(uint256 amount, bool useAttacker) public {
        // keep amount in a reasonable range but wide enough to include 1 wei.. many ethers
        amount = bound(amount, 1, 10 ether);

        // deploy attacker helper who will reenter during Put when used
        Attacker attacker = new Attacker(c);

        address caller = useAttacker ? address(attacker) : address(0xBEEF);

        // fund the caller
        vm.deal(caller, amount);

        // record previous stored balance via public getter Acc(caller).balance
        uint256 prevBalance = c.Acc(caller).balance;

        bool ok;
        if (useAttacker) {
            // if attacker is used, have it call Put and perform reentrancy in its fallback
            // attacker will call Put{value: amount}(0)
            vm.prank(caller);
            // call through attacker contract which will forward the call and reenter
            try attacker.doPut{value: amount}(0) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // normal EOA call: perform Put directly
            vm.prank(caller);
            try c.Put{value: amount}(0) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // single assertion: after Put returns (whether the call succeeded or not), the stored balance
        // for that caller equals previous + amount if the call succeeded, otherwise unchanged.
        // We assert the general rule on successful calls: final == prev + amount.
        if (ok) {
            uint256 finalBal = c.Acc(caller).balance;
            assertTrue(finalBal == prevBalance + amount);
        } else {
            // if call reverted, then balance should be unchanged
            uint256 finalBal = c.Acc(caller).balance;
            assertTrue(finalBal == prevBalance);
        }
    }
}

// Attacker that re-enters into C during Put by having fallback call Put again
contract Attacker {
    C public target;
    bool public reentered;

    constructor(C _t) payable {
        target = _t;
        reentered = false;
    }

    // entry to start the attack; will call target.Put which will call back into this contract via fallback
    function doPut(uint _unlockTime) external payable {
        // call target.Put with this contract as msg.sender (vm.prank in test sets caller externally)
        target.Put{value: msg.value}(_unlockTime);
    }

    fallback() external payable {
        // on first entry from target.Put's fallback call, attempt to reenter once
        if (!reentered) {
            reentered = true;
            // reenter target.Put again with 0 value to cause change in control flow during vulnerable Put
            // send zero value reentry to attempt to disturb accounting in mutant
            target.Put{value: 0}(0);
        }
    }
}

