pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: attacker initial deposit and reentrant re-deposit amount
    // We must deploy an adversarial contract that on receiving funds re-enters c.Put
    function testFuzz_property(uint256 initialDeposit, uint256 reentrantDeposit) public {
        // keep values in sane wide ranges and non-zero for meaningful behavior
        initialDeposit = bound(initialDeposit, 1 wei, 10 ether);
        reentrantDeposit = bound(reentrantDeposit, 1 wei, 10 ether);

        // deploy attacker that will re-enter c during Put via fallback
        Attacker attacker = new Attacker(address(c));

        // fund attacker externally so it can send value when calling Put
        vm.deal(address(attacker), initialDeposit + reentrantDeposit + 1 ether);

        // record previous balance in contract's mapping for attacker
        uint256 before = c.Acc(address(attacker));

        // have attacker call Put sending initialDeposit; attacker will re-enter and call Put again sending reentrantDeposit
        // use the attacker's call which triggers fallback -> reentrancy
        attacker.attack{value: initialDeposit}(reentrantDeposit);

        // read final recorded balance for attacker from public getter
        uint256 after = c.Acc(address(attacker));

        // Reference contract guarantees after == before + initialDeposit (because reentrancy is prevented);
        // mutant that omits locked_ = true may allow reentrant Put and break this equality for some inputs.
        assertTrue(after == before + initialDeposit);
    }
}

// Attacker contract that during Put re-enters C.Put to attempt to alter final stored balance
contract Attacker {
    C public target;
    uint256 public reentrantAmount;

    constructor(address _t) payable {
        target = C(_t);
    }

    // entry point for test: sends msg.value as initial deposit and remembers reentrant amount
    function attack(uint256 _reentrantAmount) external payable {
        reentrantAmount = _reentrantAmount;
        // call Put on target; because Attacker has a payable fallback, when target calls back to attacker (if it does),
        // the fallback will re-enter target.Put with reentrantAmount
        target.Put{value: msg.value}(0);
    }

    // fallback will be invoked if target tries to call into this contract during Put (e.g., via LogFile or other);
    // to trigger reentrancy we explicitly call back into target.Put here
    fallback() external payable {
        // if we have reentrantAmount > 0, attempt to re-enter
        if (reentrantAmount > 0) {
            uint256 amt = reentrantAmount;
            reentrantAmount = 0;
            // re-enter target.Put sending amt
            // note: this will only succeed if target's nonReentrant_ is broken
            target.Put{value: amt}(0);
        }
    }
}

